#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include "../../firmware/src/dsp/fastmath.h"
#ifndef GENERATE
#include "../../firmware/src/dsp/break_retrigger_lut.h"
#endif
static float old_probability(unsigned l,unsigned p) {
 static const uint8_t ticks[6]={3,6,12,24,48,96};
 float pbar=(float)p*0.01f, inv=(float)ticks[l]*(1.0f/96.0f);
 return pbar>=1.0f?1.0f:1.0f-fm_powf(1.0f-pbar,inv);
}
int main(void) {
#ifdef GENERATE
 puts("/* SPDX-License-Identifier: GPL-3.0-only */\n"
      "/* Generated by tests/host/break_retrigger_lut_test.c with GENERATE.\n"
      " * Exact old binary32 probabilities: 6 lengths x 100 pots x 4 = 2400 B. */\n"
      "#ifndef X0X_BREAK_RETRIGGER_LUT_H\n#define X0X_BREAK_RETRIGGER_LUT_H\n"
      "static const float brk_retrigger_lut[6][100] = {");
 for(unsigned l=0;l<6;l++) {puts("    {");for(unsigned p=0;p<100;p++)printf("        %af,%s",(double)old_probability(l,p),p%4==3?"\n":" ");puts("    },");}
 puts("};\nstatic inline float brk_retrigger_probability(unsigned length, unsigned pot)\n"
      "{\n    return pot >= 100 ? 1.0f : brk_retrigger_lut[length][pot];\n}\n#endif");
#else
 unsigned checks=0;
 for(unsigned l=0;l<6;l++)for(unsigned p=0;p<256;p++){float a=old_probability(l,p),b=brk_retrigger_probability(l,p);if(memcmp(&a,&b,4))return 1;checks++;}
 printf("BREAK probability: %u bit-exact comparisons PASS\n",checks);
#endif
 return 0;
}
